_ALL_SLUGS = {t[0] for t in ALL}
_UNRESOLVED_LINKS = {}
_RESOLVED_LINKS = [0]
_WORST_CONTRAST = [99.0]
def _render_links(escaped_text):
    def sub(m):
        target = html.unescape(m.group(1)).strip()
        label = m.group(2) if m.group(2) else target.replace("-", " ")
        t = LINK_ALIAS.get(target, target)
        if t in _ALL_SLUGS or t.startswith("http") or t.startswith("#"):
            _RESOLVED_LINKS[0]+=1
            href = f"{PG}/{t}/" if t in _ALL_SLUGS else t
            return f'<a href="{href}">{label}</a>'
        _UNRESOLVED_LINKS[target] = _UNRESOLVED_LINKS.get(target, 0) + 1
        return f'<i>{label}</i>'
    return _re.sub(r'\[\[([^\]|]+)(?:\|([^\]]*))?\]\]', sub, escaped_text)

def tile(s):
    repo, name, col, count, tag = s
    # some stored names/tags already carry entities (&amp;, &#x27;) — unescape first so
    # html.escape doesn't double-encode them into visible '&AMP;' artifacts
    name, count, tag = html.unescape(name), html.unescape(count), html.unescape(tag)
    _delay = -(sum(ord(c) for c in repo) % 26) / 10.0
    return f'''<div class="tile" style="--c:{col};--ct:{_text_tone(col)}">
      <span class="corepulse" style="animation-delay:{_delay:.1f}s"></span>
      <a class="tn tlink" href="{PG}/{repo}/">{html.escape(name)}</a><div class="tc">{html.escape(count)}</div>
      <p class="tt">{_render_links(html.escape(tag))}</p>
      <div class="tl"><span class="enter">enter ↗</span><a class="codebtn" href="{GH}/{repo}" target="_blank" rel="noopener">code</a></div>
    </div>'''

DOMAIN_IMG = {k: (f"{k}-medallion.png", "image/png") for k,_t,_a,_b in DOMAINS}   # picture-medallions: auto-use ud0/<key>-medallion.png when present (else SVG icon)
def _domain_img(key):
    if key in DOMAIN_IMG:
        fn, mime = DOMAIN_IMG[key]
        if os.path.exists(os.path.join(HERE, fn)):
            return _data_uri(fn, mime)
    return None

def _med_svg(idx, accent, key, size=118):
    """The keeper's SEAL — the neon knife-medallion SVG (dark disc, glowing accent ring, dashed
    stitch ring, the domain glyph doing the knife-dance). Reusable at any size."""
    uid = f"{key}{size}"
    glow = f'<radialGradient id="g{uid}" cx="0.5" cy="0.5" r="0.5"><stop offset="0" stop-color="{accent}" stop-opacity="0.46"/><stop offset="1" stop-color="{accent}" stop-opacity="0"/></radialGradient>'
    nf = f'<filter id="nf{uid}" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="2.6" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>'
    _img = _domain_img(key)
    if _img:
        _imgdefs = f'<clipPath id="aciclip{uid}"><circle cx="65" cy="65" r="44"/></clipPath>'
        _center = f'<g clip-path="url(#aciclip{uid})"><g class="knife" style="animation-delay:-{(idx*0.37)%2.8:.2f}s"><image href="{_img}" x="17" y="17" width="96" height="96" preserveAspectRatio="xMidYMid slice"/></g></g>'
    else:
        _imgdefs = ''
        _center = f'<g transform="translate(65,65)"><g class="knife" style="animation-delay:-{(idx*0.37)%2.8:.2f}s">{ICONS[key]}</g></g>'
    return f'''<svg class="med" viewBox="0 0 130 130" width="{size}" height="{size}" aria-hidden="true" style="color:{accent}">
      <defs>{glow}{nf}{_imgdefs}</defs>
      <circle cx="65" cy="65" r="62" fill="#0b0713"/>
      <circle cx="65" cy="65" r="60" fill="url(#g{uid})"/>
      <circle cx="65" cy="65" r="60" fill="none" stroke="{accent}" stroke-width="2.6" opacity="0.95" filter="url(#nf{uid})"/>
      <circle cx="65" cy="65" r="60" fill="none" stroke="{accent}" stroke-width="1" opacity="1"/>
      <circle class="stitch" cx="65" cy="65" r="54" fill="none" stroke="{accent}" stroke-width="1.1" stroke-dasharray="3 4" opacity="0.78"/>
      <circle cx="65" cy="65" r="45" fill="#0d0a18" stroke="{accent}" stroke-width="1" opacity="0.7"/>
      {_center}
      <text x="65" y="20" text-anchor="middle" font-family="ui-monospace,Menlo,Consolas,monospace" font-size="9" fill="{accent}" letter-spacing="1">{idx:02d}</text>
    </svg>'''

def medallion(idx, accent, key):
    return (f'<span class="medwrap kmed" data-dk="{key}" role="button" tabindex="0" '
            f'aria-label="meet this domain\'s keeper" title="meet the keeper" style="--c:{accent}">'
            + _med_svg(idx, accent, key) + '</span>')

import re as _re
import colorsys as _cs
def _lum(r,g,b):
    def f(c):
        c/=255.0
        return c/12.92 if c<=0.03928 else ((c+0.055)/1.055)**2.4
    return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)
_BGL=_lum(0xDE,0xD6,0xC7)   # tile cream #DED6C7
def _text_tone(hexcol):
    """darken a neon accent until it reads as TEXT on cream (WCAG >=4.5:1); hue kept."""
    r,g,b=int(hexcol[1:3],16),int(hexcol[3:5],16),int(hexcol[5:7],16)
    h,l,v=_cs.rgb_to_hls(r/255,g/255,b/255)
    for _ in range(64):
        ratio=(max(_BGL,_lum(r,g,b))+0.05)/(min(_BGL,_lum(r,g,b))+0.05)
        if ratio>=4.6: break
        l*=0.92
        r,g,b=[round(c*255) for c in _cs.hls_to_rgb(h,l,v)]
    final=(max(_BGL,_lum(r,g,b))+0.05)/(min(_BGL,_lum(r,g,b))+0.05)
    if final<_WORST_CONTRAST[0]: _WORST_CONTRAST[0]=final
    return f"#{r:02x}{g:02x}{b:02x}"

def _fam(slug):
    f=_re.split(r'-v\d', slug)[0]
    f=_re.sub(r'-(i{1,3}|iv|vi{1,3}|ix|x)$','',f)
    f=_re.sub(r'-\d+$','',f)
    f=_re.sub(r'-(gui|redux)$','',f)
    return f
def cluster_tile(fam, items):
    col=items[0][2]; disp=fam.replace('-',' ').upper(); n=len(items)
    chips=[]
    for r,name,c,cnt,tg in items:
        lab=r[len(fam):].lstrip('-') or r
        chips.append(f'<a class="cm" href="{PG}/{r}/" title="{html.escape(html.unescape(name))}">{html.escape(lab)}</a>')
    return f'<div class="cluster" style="--c:{col};--ct:{_text_tone(col)}"><div class="ch"><div class="cln">{html.escape(disp)}</div><div class="clc">{n} parts · merged lineage</div></div><div class="clset">{"".join(chips)}</div></div>'
def _domain_list(members):
    """Flat ALPHABETICAL list of every sphere in the domain: name + a toddler-simple
    line + a code link. Replaces the card grid inside the domain dropdown."""
    ms = sorted(members, key=lambda s: _alpha_key(html.unescape(s[1])))
    rows = []
    for s in ms:
        repo, name, col = s[0], html.unescape(s[1]), s[2]
        tod = TOD.get(repo, "")
        tod_html = html.escape(tod) if tod else '<span class="stod-none">a sphere in this domain</span>'
        rows.append(
            f'<li class="srow" style="--ct:{_text_tone(col)}">'
            f'<a class="slink" href="{PG}/{repo}/">{html.escape(name)}</a>'
            f'<span class="stod">{tod_html}</span>'
            f'<a class="scode" href="{GH}/{repo}" target="_blank" rel="noopener">code</a>'
            f'</li>')
    return f'<ul class="slist">{"".join(rows)}</ul>'

def _domain_body(key, members):
    subs = SUBDOMAINS.get(key)
    if not subs:
        return f'<div class="tiles">{render_members(members)}</div>'
    by_slug = {s[0]: s for s in members}
    used=set(); out=[]
    for label, oneline, slugs in subs:
        grp=[by_slug[sl] for sl in slugs if sl in by_slug]
        if not grp: continue
        used.update(s[0] for s in grp)
        out.append(f'<div class="subdom"><div class="subdom-h"><span class="sdt">{html.escape(label)}</span><span class="sds">{html.escape(oneline)}</span><span class="sdn">{len(grp)}</span></div><div class="tiles">{render_members(grp)}</div></div>')
    rest=[s for s in members if s[0] not in used]
    if rest:
        out.append(f'<div class="subdom"><div class="subdom-h"><span class="sdt">·&nbsp;other</span><span class="sds">not yet grouped in a subdomain</span><span class="sdn">{len(rest)}</span></div><div class="tiles">{render_members(rest)}</div></div>')
    return "".join(out)

def render_members(members):
    members = sorted(members, key=lambda s: _re.sub(r'^the-', '', s[0]))   # alphabetized within the domain (leading 'the-' ignored); families stay contiguous by shared prefix
    order=[]; groups={}
    for s in members:
        f=_fam(s[0])
        groups.setdefault(f,[]) or order.append(f) if f not in groups else None
        if f not in groups: groups[f]=[]
        groups[f].append(s)
    # rebuild cleanly (the one-liner above is fragile)
    order=[]; groups={}
    for s in members:
        f=_fam(s[0])
        if f not in groups: groups[f]=[]; order.append(f)
        groups[f].append(s)
    out=[]
    for f in order:
        items=groups[f]
        if len(items)>=2 and len(f)>=4 and any(it[0]!=f for it in items):
            out.append(cluster_tile(f,items))
        else:
            out.extend(tile(s) for s in items)
    return "".join(out)

import unicodedata as _ud
def _alpha_key(title):
    t=_ud.normalize('NFD', title)
    t=''.join(c for c in t if not _ud.combining(c)).upper()
    if t.startswith('THE '): t=t[4:]
    return t
# alphabetical DISPLAY order; the enumerate index (the domain's number) travels with it
DOMAINS_ALPHA = sorted(enumerate(DOMAINS, 1), key=lambda t: _alpha_key(t[1][1]))
def domains_html():
    out = []
    for i,(key,title,accent,blurb) in DOMAINS_ALPHA:
        members = BY_DOMAIN[key]
        # L1 is the DOMAIN DIRECTORY — no spheres. The medallion opens the keeper panel;
        # the meta + blurb bridge to the keeper's own page (L2) at d/<key>.html.
        blurb_html = _re.sub(r'<a\b[^>]*>(.*?)</a>', r'<i class="dref">\1</i>', _render_links(blurb))
        bare_len = len(_re.sub(r'<[^>]+>|&[a-z#0-9]+;', '', blurb))
        lead = ' lead' if bare_len < 175 else ''
        href = f'd/{key}.html'
        cnt = f'{len(members)} {"sphere" if len(members)==1 else "spheres"}'
        out.append(f'''<section class="domain" id="{key}" style="--c:{accent};--ct:{_text_tone(accent)}">
      <div class="dhead">
        {medallion(i, accent, key)}
        <a class="dmeta dlink" href="{href}"><div class="dnum">DOMAIN {i:02d} / {len(DOMAINS):02d}</div><h2 class="dtitle">{title}</h2>
          <div class="dcount">{cnt} <span class="denter">enter the domain →</span></div></a>
        <a class="dblurb{lead} dlink" href="{href}"><span class="dbx">{blurb_html}</span></a>
      </div>
    </section>''')
    return "\n".join(out)


