def l2_page_metaxy(i, key, title, accent, blurb, members):
    """METAXÝ · the between — a bespoke keeper page (AVAN + TOP + THE BETWEEN, who chose this of
    three). A permeable cell-membrane threshold runs down the middle: NOT-YET (non-living) on the
    left, ALIVE (living) on the right, and the 16 spheres suspended IN the between — each drifting
    across the membrane and back, never wholly on either side, rippling the boundary as it crosses.
    Hover names, click enters. Deep teal-violet ground, a shimmering teal bilayer."""
    import json as _pj
    tclean, role, honest = _keeper_voice(title, blurb)
    n = len(members); ND = len(DOMAINS)
    def _nm(m): return html.unescape(_re.sub(r'<[^>]+>', '', m[1]))
    rows = "".join(
        f'<a class="nrow" href="{PG}/{m[0]}/" data-k="{html.escape((m[0]+" "+_nm(m)).lower())}">'
        f'<span class="ndot" style="background:{m[2]}"></span>'
        f'<span class="nn">{html.escape(_nm(m))}</span>'
        f'<span class="nsub">{html.escape(html.unescape(_re.sub(r"<[^>]+>","",(m[3] if len(m)>3 else ""))))[:60]}</span>'
        f'<span class="narr">&#8594;</span></a>'
        for m in members)
    data = _pj.dumps({"c": accent, "sph": [{"s": m[0], "n": _nm(m), "c": m[2], "u": f"{PG}/{m[0]}/"} for m in members]},
                     ensure_ascii=False, separators=(',', ':'))
    ethos = ('<p class="ethos">' + html.escape(honest) + '</p>') if honest else ''
