  g.fillStyle='rgba('+VI[0]+','+VI[1]+','+VI[2]+',0.8)';g.font='10px ui-monospace,Menlo,Consolas,monospace';g.fillText('≡ read across the seam · a crossing, not a copy',rx0+8,anchorY+30);
