    g.fillStyle='rgba(210,224,255,0.5)';g.font=(Math.max(7,R*0.24)|0)+'px ui-monospace,Menlo,monospace';g.textAlign='center';g.fillText('|0⟩',q.x,q.y-R-3);g.fillText('|1⟩',q.x,q.y+R+9);
