    g.fillStyle='rgba('+BM[0]+','+BM[1]+','+BM[2]+','+(0.12*bw)+')';g.beginPath();g.moveTo(ship.x,ship.y);g.lineTo(tg.x+perp[0]*8,tg.y+perp[1]*8);g.lineTo(tg.x-perp[0]*8,tg.y-perp[1]*8);g.closePath();g.fill();
